    ],
    correct: new Set(['c', 'rust', 'cpp']),
  },
  {
    id: 'q3',
    text: 'Which of the following languages support first-class functions?',
    options: [
      { value: 'javascript', label: 'JavaScript' },
      { value: 'haskell',    label: 'Haskell' },
      { value: 'python',     label: 'Python' },
      { value: 'cobol',      label: 'COBOL' },
    ],
    correct: new Set(['javascript', 'haskell', 'python']),
  },
];

function getSelected(questionId) {
  return new Set(
    [...document.querySelectorAll(`[name="${questionId}"]:checked`)]
      .map(cb => cb.value)
  );
}

function setsEqual(a, b) {
  return a.size === b.size && [...a].every(v => b.has(v));
}

function correctAnswerNames(q) {
  return [...q.correct]
    .map(val => q.options.find(o => o.value === val)?.label)
    .filter(Boolean)
    .join(', ');
}

document.getElementById('quiz-form').addEventListener('submit', function (e) {
  e.preventDefault();
  let score = 0;

  questions.forEach(q => {
    const selected = getSelected(q.id);
    const isCorrect = setsEqual(selected, q.correct);
    if (isCorrect) score++;

    const field = document.getElementById(`field-${q.id}`);
    field.classList.toggle('correct', isCorrect);
    field.classList.toggle('incorrect', !isCorrect);

    const reveal = field.querySelector('.answer-reveal');
    if (!isCorrect) {
      reveal.textContent = `Correct answer${q.correct.size > 1 ? 's' : ''}: ${correctAnswerNames(q)}`;
    }
  });

  const banner = document.getElementById('result-banner');
  banner.querySelector('.result-score').textContent = `${score} / ${questions.length}`;
  const pct = Math.round((score / questions.length) * 100);
  banner.querySelector('.result-label').textContent =
    pct === 100 ? '🎉 Perfect score!' :
    pct >= 67  ? '👍 Nice work!' :
    pct >= 34  ? '📚 Keep studying!' :
                 '💡 Review the material and try again.';
  banner.classList.add('visible');

  document.getElementById('quiz-form').classList.add('submitted');
  document.getElementById('btn-submit').style.display = 'none';
  document.getElementById('btn-retry').style.display = 'inline-block';

  banner.scrollIntoView({ behavior: 'smooth', block: 'start' });
});

document.getElementById('btn-retry').addEventListener('click', function () {
  document.getElementById('quiz-form').reset();
  document.getElementById('quiz-form').classList.remove('submitted');

  questions.forEach(q => {
    const field = document.getElementById(`field-${q.id}`);
    field.classList.remove('correct', 'incorrect');
    field.querySelector('.answer-reveal').textContent = '';
  });

  document.getElementById('result-banner').classList.remove('visible');
  document.getElementById('btn-submit').style.display = 'inline-block';
  this.style.display = 'none';

  window.scrollTo({ top: 0, behavior: 'smooth' });
});
